-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.hook_before_user_created(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if public.is_invited(event -> 'user' ->> 'email') then
    return '{}'::jsonb;
  end if;
  if public.is_allowed_email(event -> 'user' ->> 'email') then
    return jsonb_build_object(
      'error', jsonb_build_object(
        'http_code', 403,
        'message', 'El Quinto Ventrículo está en prueba: por ahora solo entran cuentas invitadas. '
                   || 'Si deberías tener acceso, escribe a contacto@quintoventriculo.cl.'));
  end if;
  return jsonb_build_object(
    'error', jsonb_build_object(
      'http_code', 403,
      'message', 'El Quinto Ventrículo es solo para cuentas @ug.uchile.cl.'));
end;
$function$;

grant execute on function public.hook_before_user_created(event jsonb) to service_role;
grant execute on function public.hook_before_user_created(event jsonb) to supabase_auth_admin;
